-- Remove duplicate watchlist rows that would collapse onto the same stable movie id.
-- Remove duplicate rating rows that would collapse onto the same stable movie id.
-- Remap existing movie references to the stable seeded ids before the catalog rows are rewritten.
commit;

insert into public.movies (
  external_id,
  title,
  year,
  genre,
  director,
  writers,
  cast_members,
  age_rating,
  overview,
  synopsis,
  poster_url,
  source_key
)
select
  external_id,
  title,
  year,
  genre,
  director,
  writers,
  cast_members,
  age_rating,
  overview,
  synopsis,
  poster_url,
  source_key
from temp_movies_seed
on conflict (external_id) do update
set
  title = excluded.title,
  year = excluded.year,
  genre = excluded.genre,
  director = excluded.director,
  writers = excluded.writers,
  cast_members = excluded.cast_members,
  age_rating = excluded.age_rating,
  overview = excluded.overview,
  synopsis = excluded.synopsis,
  poster_url = excluded.poster_url,
  source_key = excluded.source_key;

-- Non-destructive chunk import: table cleanup is intentionally skipped for chunked uploads.
commit;